// Accepts: plain JSON form, Typeform (form_response.answers) or Tally (data.fields). Emits a Brand partial (API.md).
const raw = $input.first().json;
const body = raw.body || {};
let f = { ...(raw.query || {}), ...body };
if (body.form_response && Array.isArray(body.form_response.answers)) {
  f = {};
  for (const a of body.form_response.answers) {
    const key = (a.field && (a.field.ref || a.field.id)) || 'field';
    f[key] = a.text ?? a.email ?? a.phone_number ?? a.url ?? a.number ?? (a.choice && a.choice.label) ?? (a.choices && a.choices.labels && a.choices.labels.join(', ')) ?? null;
  }
}
if (body.data && Array.isArray(body.data.fields)) {
  f = {};
  for (const x of body.data.fields) f[x.key || x.label] = x.value;
}
const pick = (...keys) => { for (const k of keys) { if (f[k] !== undefined && f[k] !== null && String(f[k]).trim() !== '') return String(f[k]).trim(); } return ''; };
const honeypot = pick('website_url_confirm', '_hp', 'fax');
const name = pick('brandName', 'brand', 'company', 'companyName', 'name_of_company', 'organisation');
const contactName = pick('contactName', 'name', 'fullName', 'full_name', 'firstName');
const email = pick('email', 'work_email', 'contact_email').toLowerCase();
const website = pick('website', 'url', 'site');
const lang = (pick('lang', 'language') || 'id').slice(0, 2).toLowerCase();
const budgetRaw = pick('budgetIDR', 'budget', 'monthly_budget');
const budgetIDR = Number(String(budgetRaw).replace(/[^0-9]/g, '')) || null;
const validEmail = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email);
const valid = !honeypot && !!name && validEmail;
const typeGuess = /agency|agensi|وكالة/i.test(pick('type', 'companyType') + ' ' + name) ? 'agency' : 'brand';
const brand = {
  name, type: pick('type', 'companyType') || typeGuess,
  industry: pick('industry', 'category', 'vertical') || 'other',
  size: pick('size', 'companySize') || 'smb',
  country: (pick('country') || 'ID').toUpperCase().slice(0, 2),
  website,
  contacts: [{ name: contactName || name, role: pick('role', 'jobTitle', 'title') || 'Contact', email, linkedin: pick('linkedin', 'linkedin_url') || null, whatsapp: pick('whatsapp', 'phone') || null, lang: ['en', 'ar', 'id'].includes(lang) ? lang : 'id' }],
  products: pick('products', 'product').split(/[,;]/).map(s => s.trim()).filter(Boolean),
  targetAudience: pick('targetAudience', 'audience', 'goal', 'message', 'notes'),
  budgetIDR,
  pipeline: 'lead',
  source: 'n8n',
  notes: 'Inbound via ' + (body.form_response ? 'typeform' : body.data ? 'tally' : 'web form') + ' at ' + new Date().toISOString(),
};
// UU PDP data minimisation: only keep the fields above; the raw form is not forwarded.
return [{ json: { valid, reason: valid ? null : (honeypot ? 'honeypot' : !name ? 'missing_company' : 'invalid_email'), brand } }];

const wanted = $('Normalize lead').first().json.brand;
const items = (($input.first().json || {}).items) || [];
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const exact = items.find(b => norm(b.name) === norm(wanted.name));
const brand = exact || items[0] || null;
return [{ json: { brandId: brand ? brand.id : null, brandName: wanted.name, contactEmail: wanted.contacts[0].email, lang: wanted.contacts[0].lang, budgetIDR: wanted.budgetIDR, industry: wanted.industry } }];

